BEGIN;
CREATE TABLE IF NOT EXISTS dojos (id text PRIMARY KEY,name text NOT NULL,slug text UNIQUE NOT NULL,status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),CHECK (status IN ('active','suspended','archived')));
CREATE TABLE IF NOT EXISTS dojo_memberships (id text PRIMARY KEY,dojo_id text NOT NULL REFERENCES dojos(id) ON DELETE CASCADE,user_id text NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,membership_role text NOT NULL,status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(dojo_id,user_id,membership_role),CHECK (membership_role IN ('practitioner','instructor','evaluator','guardian','admin')),CHECK (status IN ('active','suspended','ended')));
CREATE INDEX IF NOT EXISTS dojo_memberships_user_idx ON dojo_memberships(user_id,status);
CREATE TABLE IF NOT EXISTS dojo_classes (id text PRIMARY KEY,dojo_id text NOT NULL REFERENCES dojos(id) ON DELETE CASCADE,name text NOT NULL,belt_scope text,instructor_user_id text NOT NULL REFERENCES user_profiles(id) ON DELETE RESTRICT,status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),CHECK (status IN ('active','paused','archived')));
CREATE TABLE IF NOT EXISTS dojo_class_members (class_id text NOT NULL REFERENCES dojo_classes(id) ON DELETE CASCADE,user_id text NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,status text NOT NULL DEFAULT 'active',joined_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(class_id,user_id),CHECK (status IN ('active','paused','ended')));
CREATE TABLE IF NOT EXISTS dojo_sessions (id text PRIMARY KEY,dojo_id text NOT NULL REFERENCES dojos(id) ON DELETE CASCADE,class_id text REFERENCES dojo_classes(id) ON DELETE SET NULL,instructor_user_id text NOT NULL REFERENCES user_profiles(id) ON DELETE RESTRICT,session_type text NOT NULL,title text NOT NULL,canonical_entity_ids jsonb NOT NULL DEFAULT '[]'::jsonb,safety_profile jsonb NOT NULL DEFAULT '{}'::jsonb,notes text,starts_at timestamptz NOT NULL,ends_at timestamptz,status text NOT NULL DEFAULT 'planned',created_at timestamptz NOT NULL DEFAULT now(),CHECK (status IN ('planned','active','completed','cancelled')),CHECK (session_type IN ('curriculum-class','technical-lab','representative-practice','sparring-lab','pfi-strength','pfi-endurance','pfi-integrated-conditioning','kinetic-arts','integral-practice','open-lab','assessment','research-lab')));
CREATE INDEX IF NOT EXISTS dojo_sessions_dojo_start_idx ON dojo_sessions(dojo_id,starts_at DESC);
CREATE TABLE IF NOT EXISTS dojo_attendance (session_id text NOT NULL REFERENCES dojo_sessions(id) ON DELETE CASCADE,user_id text NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,status text NOT NULL,checked_in_at timestamptz,PRIMARY KEY(session_id,user_id),CHECK (status IN ('expected','present','absent','excused')));
CREATE TABLE IF NOT EXISTS safety_incidents (id text PRIMARY KEY,dojo_id text NOT NULL REFERENCES dojos(id) ON DELETE RESTRICT,session_id text REFERENCES dojo_sessions(id) ON DELETE SET NULL,reporter_user_id text NOT NULL REFERENCES user_profiles(id) ON DELETE RESTRICT,subject_user_id text REFERENCES user_profiles(id) ON DELETE SET NULL,incident_type text NOT NULL,severity text NOT NULL,summary text NOT NULL,actions_taken text NOT NULL,status text NOT NULL DEFAULT 'open',occurred_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz,CHECK (incident_type IN ('incident','near-miss','hard-stop','safeguarding')),CHECK (severity IN ('low','moderate','high','critical')),CHECK (status IN ('open','under-review','resolved','archived')));
CREATE INDEX IF NOT EXISTS safety_incidents_dojo_idx ON safety_incidents(dojo_id,status,occurred_at DESC);
COMMIT;
